INSERT INTO cyber_modules (id, title, original_title, difficulty, min_read_seconds, intel_content) VALUES ('mod_morse', 'Audio Protocol', 'Sandi Morse', 1, 20, '{"brief":"Decode pulse sequences into readable commands.","headline":"Audio Protocol","steps":["Short pulse = dot.","Long pulse = dash.","Group pulses into letters."]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, intel_content = EXCLUDED.intel_content;
INSERT INTO cyber_modules (id, title, original_title, difficulty, min_read_seconds, intel_content) VALUES ('mod_angka', 'Numeric Hash', 'Sandi Angka', 1, 20, '{"brief":"Numbers map directly to alphabet positions.","headline":"Numeric Hash","steps":["1 = A, 2 = B, 3 = C.","Split long sequences into chunks.","Rebuild the phrase."]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, intel_content = EXCLUDED.intel_content;
INSERT INTO cyber_modules (id, title, original_title, difficulty, min_read_seconds, intel_content) VALUES ('mod_abjad', 'Voice Auth Protocol', 'Sandi Abjad Inter', 1, 20, '{"brief":"Alternate alphabet shift using paired signals.","headline":"Voice Auth Protocol","steps":["Identify the current index.","Apply interleaved mapping.","Confirm with checksum word."]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, intel_content = EXCLUDED.intel_content;
INSERT INTO cyber_modules (id, title, original_title, difficulty, min_read_seconds, intel_content) VALUES ('mod_kotak1', 'Geo-Lock Grid', 'Sandi Kotak 1', 2, 25, '{"brief":"Decode using a square grid coordinate map.","headline":"Geo-Lock Grid","steps":["Locate row and column intersections.","Read coordinates in sequence.","Reconstruct the message."]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, intel_content = EXCLUDED.intel_content;
INSERT INTO cyber_modules (id, title, original_title, difficulty, min_read_seconds, intel_content) VALUES ('mod_rumput', 'Spectrum Analysis', 'Sandi Rumput', 2, 25, '{"brief":"Wave blades indicate letter shifts.","headline":"Spectrum Analysis","steps":["Count blade patterns.","Match to alphabet offsets.","Verify with anchor words."]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, intel_content = EXCLUDED.intel_content;
INSERT INTO cyber_modules (id, title, original_title, difficulty, min_read_seconds, intel_content) VALUES ('mod_semaphore', 'Vector Signaling', 'Semaphore', 2, 25, '{"brief":"Two-flag vectors encode letters.","headline":"Vector Signaling","steps":["Match vector angles to letters.","Read pairs in sequence.","Validate with a keyword."]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, intel_content = EXCLUDED.intel_content;
INSERT INTO cyber_modules (id, title, original_title, difficulty, min_read_seconds, intel_content) VALUES ('mod_coord', 'Matrix Coordinates', 'Sandi Merah Putih', 2, 25, '{"brief":"Dual-tone coordinates unlock entries.","headline":"Matrix Coordinates","steps":["Map red/white axis positions.","Combine into grid coordinates.","Extract final text."]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, intel_content = EXCLUDED.intel_content;
INSERT INTO cyber_modules (id, title, original_title, difficulty, min_read_seconds, intel_content) VALUES ('mod_ular', 'Serpentine Routing', 'Sandi Ular', 3, 30, '{"brief":"Follow a snake path to decode data.","headline":"Serpentine Routing","steps":["Trace the serpentine path.","Read characters in order.","Confirm with checksum."]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, intel_content = EXCLUDED.intel_content;
INSERT INTO cyber_modules (id, title, original_title, difficulty, min_read_seconds, intel_content) VALUES ('mod_napoleon', 'Block Transposition', 'Sandi Napoleon', 3, 30, '{"brief":"Reorder blocks to reveal plaintext.","headline":"Block Transposition","steps":["Split into equal blocks.","Reorder using key pattern.","Merge into final text."]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, intel_content = EXCLUDED.intel_content;
INSERT INTO cyber_modules (id, title, original_title, difficulty, min_read_seconds, intel_content) VALUES ('mod_jepang', 'Vertical Stack Processing', 'Sandi Jepang', 3, 30, '{"brief":"Read vertically to decode messages.","headline":"Vertical Stack Processing","steps":["Stack characters into columns.","Read top-to-bottom order.","Validate using marker token."]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, intel_content = EXCLUDED.intel_content;
INSERT INTO cyber_modules (id, title, original_title, difficulty, min_read_seconds, intel_content) VALUES ('mod_siput', 'Vortex Algorithm', 'Sandi Siput', 3, 30, '{"brief":"Spiral readout reveals hidden strings.","headline":"Vortex Algorithm","steps":["Start from outer ring.","Spiral inward by direction.","Assemble output."]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, intel_content = EXCLUDED.intel_content;
INSERT INTO cyber_modules (id, title, original_title, difficulty, min_read_seconds, intel_content) VALUES ('mod_an', 'Mirror Encryption', 'Sandi AN/AZ', 4, 35, '{"brief":"Reflect characters over the alphabet axis.","headline":"Mirror Encryption","steps":["A \u003c-\u003e Z, B \u003c-\u003e Y mapping.","Swap each letter.","Review integrity."]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, intel_content = EXCLUDED.intel_content;
INSERT INTO cyber_modules (id, title, original_title, difficulty, min_read_seconds, intel_content) VALUES ('mod_sisipan', 'Noise Filtering', 'Sandi Sisipan', 4, 35, '{"brief":"Remove injected noise to reveal plaintext.","headline":"Noise Filtering","steps":["Identify noise tokens.","Strip filler characters.","Rebuild clean message."]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, intel_content = EXCLUDED.intel_content;
INSERT INTO cyber_modules (id, title, original_title, difficulty, min_read_seconds, intel_content) VALUES ('mod_kurung', 'Syntax Logic', 'Sandi Kurung', 4, 35, '{"brief":"Bracket logic defines message order.","headline":"Syntax Logic","steps":["Resolve nested brackets.","Apply execution order.","Decode final string."]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, intel_content = EXCLUDED.intel_content;
