INSERT INTO sku_points (id, level, number, title, description, category, quiz_content) VALUES ('bantara_01', 'bantara', 1, 'Agama & Ketuhanan', 'Uji pemahaman dasar ketakwaan dan logika ibadah dalam situasi penegak.', 'Agama', '{"questions":[{"correct_index":0,"options":["Dijamak dan diqashar","Dibatalkan","Ditunda tanpa alasan","Tidak boleh shalat"],"question":"Saat perjalanan jauh, ketentuan shalat yang tepat adalah..."},{"correct_index":1,"options":["Takut tanpa usaha","Menjaga ibadah dan akhlak","Hanya taat ketika diawasi","Menolak nasihat"],"question":"Makna sikap takwa dalam konteks Penegak adalah..."},{"correct_index":1,"options":["Pilih salah satu ekstrem","Cari keseimbangan sesuai prioritas syariat","Abaikan keduanya","Tunggu instruksi teman"],"question":"Keputusan paling bijak saat ada konflik ibadah dan tugas sosial adalah..."}]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, quiz_content = EXCLUDED.quiz_content;
INSERT INTO sku_points (id, level, number, title, description, category, quiz_content) VALUES ('bantara_10', 'bantara', 10, 'PBB: Komando & Orientasi', 'Studi kasus komando dan orientasi barisan setelah melakukan Balik Kanan.', 'PBB', '{"questions":[{"correct_index":1,"options":["Tetap menghadap depan","Berbalik 180 derajat","Menghadap kiri","Menghadap kanan"],"question":"Setelah perintah Balik Kanan, orientasi barisan menjadi..."},{"correct_index":1,"options":["Jarak bebas","Keseragaman arah hadap","Kecepatan lari","Jumlah barisan berkurang"],"question":"Komandan harus memastikan apa setelah Balik Kanan?"},{"correct_index":1,"options":["Biarkan","Perbaiki dengan koreksi komando","Hentikan latihan","Ganti anggota"],"question":"Jika satu anggota salah arah setelah Balik Kanan, tindakan yang benar adalah..."}]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, quiz_content = EXCLUDED.quiz_content;
INSERT INTO sku_points (id, level, number, title, description, category, quiz_content) VALUES ('bantara_12', 'bantara', 12, 'Logo & Tanda Pengenal', 'Pengenalan bentuk dan makna simbol kepramukaan.', 'Logo', '{"questions":[{"correct_index":1,"options":["Keangkuhan","Kemandirian dan daya guna","Kelemahan","Keberanian saja"],"question":"Tunas kelapa melambangkan..."},{"correct_index":1,"options":["Pajangan","Identitas dan jenjang","Hiasan seragam","Pengganti tanda pangkat TNI"],"question":"Fungsi utama tanda pengenal pramuka adalah..."},{"correct_index":0,"options":["Gerakan Pramuka Indonesia","PMR","OSIS","Paskibra"],"question":"Siluet tunas kelapa identik dengan identitas..."}]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, quiz_content = EXCLUDED.quiz_content;
INSERT INTO sku_points (id, level, number, title, description, category, quiz_content) VALUES ('bantara_19', 'bantara', 19, 'Kesehatan & Olahraga', 'Prosedur keselamatan penyelamatan di air secara teori.', 'Kesehatan', '{"questions":[{"correct_index":1,"options":["Langsung lompat","Pastikan keselamatan penolong","Menunggu instruktur","Merekam"],"question":"Langkah pertama saat melihat korban tenggelam adalah..."},{"correct_index":1,"options":["Rokok","Tongkat/pelampung","Batu besar","Payung"],"question":"Alat bantu yang paling aman digunakan adalah..."},{"correct_index":1,"options":["Memberi makan","Cek napas dan kesadaran","Menyuruh berdiri","Mengajak jalan"],"question":"Setelah korban ditarik ke tepi, tindakan awal adalah..."}]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, quiz_content = EXCLUDED.quiz_content;
INSERT INTO sku_points (id, level, number, title, description, category, quiz_content) VALUES ('bantara_22', 'bantara', 22, 'Navigasi & Peta', 'Logika pembacaan peta dan azimut dasar.', 'Navigasi', '{"questions":[{"correct_index":1,"options":["Utara","Timur","Selatan","Barat"],"question":"Azimut 90 derajat menunjuk ke arah..."},{"correct_index":2,"options":["Datar","Lembah dangkal","Kemiringan curam","Area air"],"question":"Garis kontur rapat pada peta menandakan..."},{"correct_index":1,"options":["Perkiraan mata","Membandingkan jarak peta ke jarak nyata","Menghitung langkah tanpa alat","Mengabaikan legenda"],"question":"Cara paling tepat membaca skala peta adalah..."}]}') ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title, quiz_content = EXCLUDED.quiz_content;
